/* @lc app=leetcode id=3296 lang=kotlin */ class Solution { fun ok(h: Int, w: IntArray, T: Long): Boolean = w.sumOf { t -> (T / t).let { q -> ((Math.sqrt(1.0 + 8.0 * q) - 1) / 2).toLong().let { x -> if (x * (x + 1) / 2 > q) x - 1 else if ((x + 1) * (x + 2) / 2 <= q) x + 1 else x } } } >= h fun minNumberOfSeconds(mountainHeight: Int, workerTimes: IntArray): Long = generateSequence(1L to 6_000_000_000_000_000L) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (ok(mountainHeight, workerTimes, m)) lo to m else m + 1 to hi } }.last().first }